import { Button, Card, Input, Select, Stack, Switch } from '@jinx-ui/react';

type InterfaceLanguage = 'ru' | 'en';

type ProfileSettings = {
  name: string;
  language: InterfaceLanguage;
  emailNotifications: boolean;
};

type ProfileSettingsFormProps = {
  initialSettings?: ProfileSettings;
  onSave: (settings: ProfileSettings) => void;
};

const languageOptions: Array<{ value: InterfaceLanguage; label: string }> = [
  { value: 'ru', label: 'Русский' },
  { value: 'en', label: 'Английский' },
];

const defaultSettings: ProfileSettings = {
  name: '',
  language: 'ru',
  emailNotifications: false,
};

export default function ProfileSettingsForm({
  initialSettings = defaultSettings,
  onSave,
}: ProfileSettingsFormProps) {
  const [name, setName] = useState(initialSettings.name);
  const [language, setLanguage] = useState<InterfaceLanguage>(initialSettings.language);
  const [emailNotifications, setEmailNotifications] = useState(initialSettings.emailNotifications);

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    onSave({ name: name.trim(), language, emailNotifications });
  };

  return (
    <Card>
      <form onSubmit={handleSubmit} style={{ padding: 'var(--jx-space-4)' }}>
        <Stack direction="column" gap="md">
